Tìm số đo ${x}$ trong hình sau. 

\choice
{ \True $100^{\circ}$  }
   {  $174^{\circ}$ }
     { $172^{\circ}$  }
    {  $214^{\circ}$ }
}{
\begin{tikzpicture}
        % Draw the quadrilateral
        \coordinate (A) at (0, 0);
        \coordinate (B) at (1, 3);
        \coordinate (C) at (5, 4);
        \coordinate (D) at (6, 0);

        \draw (A) -- (B) -- (C) -- (D) -- cycle;

        % Label the points
        \node[below left] at (A) {$A$};
        \node[above left] at (B) {$B$};
        \node[above] at (C) {$C$};
        \node[below right] at (D) {$D$};

        % Draw and label the angles
       \draw 
    (B) pic[draw,angle radius = 12] {angle =A--B--C} node[shift={(-35:25pt)}]{$ 114^\circ $} 
    (A) pic[draw,angle radius = 12] {angle =D--A--B} node[shift={(25:20pt)}]{$ 72^\circ $}  
    (D) pic[draw,angle radius = 12] {angle =C--D--A} node[shift={(-25:-20pt)}]{$ 74^\circ $} 
    (C) pic[draw,angle radius = 12] {angle =B--C--D} node[shift={(55:-20pt)}]{$ x^\circ $}   
    ;

    \end{tikzpicture}
}
\loigiai{
Vì tổng các góc của một tứ giác bằng $360^\circ$ nên số đo $x$ bằng: $x = 360^\circ - (114^\circ + 72^\circ + 74^\circ) = 100^\circ$.
}\end{ex}

