Tìm số đo ${x}$ trong hình sau. 

\choice
{ \True $104^{\circ}$  }
   {  $179^{\circ}$ }
     { $173^{\circ}$  }
    {  $216^{\circ}$ }
}{
\begin{tikzpicture}
        % Draw the quadrilateral
        \coordinate (A) at (0, 0);
        \coordinate (B) at (1, 3);
        \coordinate (C) at (5, 4);
        \coordinate (D) at (6, 0);

        \draw (A) -- (B) -- (C) -- (D) -- cycle;

        % Label the points
        \node[below left] at (A) {$A$};
        \node[above left] at (B) {$B$};
        \node[above] at (C) {$C$};
        \node[below right] at (D) {$D$};

        % Draw and label the angles
       \draw 
    (B) pic[draw,angle radius = 12] {angle =A--B--C} node[shift={(-35:25pt)}]{$ 112^\circ $} 
    (A) pic[draw,angle radius = 12] {angle =D--A--B} node[shift={(25:20pt)}]{$ 69^\circ $}  
    (D) pic[draw,angle radius = 12] {angle =C--D--A} node[shift={(-25:-20pt)}]{$ 75^\circ $} 
    (C) pic[draw,angle radius = 12] {angle =B--C--D} node[shift={(55:-20pt)}]{$ x^\circ $}   
    ;

    \end{tikzpicture}
}
\loigiai{
Vì tổng các góc của một tứ giác bằng $360^\circ$ nên số đo $x$ bằng: $x = 360^\circ - (112^\circ + 69^\circ + 75^\circ) = 104^\circ$.
}\end{ex}

